% The COBRAToolbox: testSlvrEMU_fast.m
%
% Purpose:
%     - slvrEMU_fast is the optimised EMU (elementary metabolite unit) solver generated by
%       generateIsotopomerSolver (Perl scripts generatorEMU.pl and optimizerEMU.pl) for the
%       E. coli isotopomer model of testFitC13Data (model.mat, 335 reactions). Given a flux vector
%       and the glucose label input as mass distribution vectors (MDVs) of glucose fragments
%       (convertCarbonInput), it solves nine levels of sparse linear systems and returns the
%       MDVs of 36 amino-acid fragments. The test uses the fixtures of this folder: the
%       steady-state flux vector v0 (point.mat, |S*v0| < 3e-12) and the label input of
%       expdata.mat, and checks
%         * the 36 output fields and the length of each MDV (number of carbons in the fragment
%           name + 1), that each MDV sums to 1 and is nonnegative (MDVs are distributions);
%         * that an unlabelled glucose input gives the MDV [1 0 ... 0] for every fragment
%           (no 13C enters the network: independent derivation);
%         * agreement with slvrEMU, the unoptimised EMU solver generated from the same model;
%         * four MDVs against the first run (Tier 5 reference values, see below).
%
% Function under test:
%     src/dataIntegration/fluxomics/c13solver/slvrEMU_fast.m
%
% Tier (Constitution III-Coverage):
%     Tier 3 - the function under test is written in the test by generateIsotopomerSolver, whose
%     flux variability step needs an LP solver and whose scripts need Perl (declared with
%     prepareTest). The function itself uses no solver (the linear systems are solved by
%     solveLin with backslash) and no genome-scale model: the flux vector and label input are
%     the small fixtures point.mat and expdata.mat of this folder. The four reference MDVs of
%     the last section were generated by the first run (2026-11-15, MATLAB R2025a, no
%     optimisation solver) and are not derived independently; they guard consistency.
%
% Coverage exemptions:
%     None. Every executable line is reached below (the function is straight-line code).
%
% Known defects documented (NOT tested, NOT fixed here):
%     None found.
%
% Authors:
%     - Generated for feature 20261113-142115-test-backfill-tiers, 2026-11-15.
%     - Generates the solver files it tests itself, as the CI run has none (T035), 2026-11-20.

% save the current path
currentDir = pwd;

% initialize the test
fileDir = fileparts(which('testSlvrEMU_fast'));
cd(fileDir);

% declare the requirements of this test: an LP solver and Perl, both used only to generate
% the solver files below
solvers = prepareTest('needsLP', true, 'requiredSoftwares', {'perl'});

% the solver files (slvr*.m, convertCarbonInput.m) are written by generateIsotopomerSolver for
% a given model and are not kept in the repository (.gitignore); generate them here for
% model.mat of this folder, as testFitC13Data does. Solver files present now (perhaps generated
% for another model) are copied to a temporary folder and put back at the end
c13Dir = fileparts(which('generateIsotopomerSolver'));
c13Files = {'IsotopomerModel.txt'; 'convertCarbonInput.m'; 'slvrCumomer.m'; 'slvrCumomer_fast.m'; ...
    'slvrEMU.m'; 'slvrEMU_fast.m'};
c13Existed = cellfun(@(f) exist(fullfile(c13Dir, f), 'file') == 2, c13Files);
c13Backup = tempname;
mkdir(c13Backup);
for k = find(c13Existed)'
    copyfile(fullfile(c13Dir, c13Files{k}), c13Backup);
end
changeCobraSolver(solvers.LP{1}, 'LP', 0);
c13Fixtures = load('model.mat', 'model');
c13Fixtures.expdata = getfield(load('expdata.mat', 'expdata'), 'expdata');
% true: leave out the reactions that carry no flux in any steady state (flux variability), as
% testFitC13Data does
generateIsotopomerSolver(c13Fixtures.model, 'xglcDe', c13Fixtures.expdata, true);
clear c13Fixtures
% make MATLAB read the new files, not versions of them it may hold in memory
rehash;
clear convertCarbonInput slvrCumomer slvrCumomer_fast slvrEMU slvrEMU_fast

% solveLin (called by the function) turns the warning MATLAB:nearlySingularMatrix off and does
% not turn it on again; save its state to restore it at the end
nearlySingularState = warning('query', 'MATLAB:nearlySingularMatrix');

% cdv2idv and idv2cdv (used by convertCarbonInput and below) cache matrices in global
% variables; note the globals that exist now to remove the new ones at the end
globalsBefore = who('global');

% fixtures of this folder (shared with testFitC13Data): the flux vector v0 of model.mat and
% the glucose label input expdata.input (64 isotopomer fractions, converted to fragment MDVs)
load('point.mat', 'v0');
load('expdata.mat', 'expdata');
glucoseInput = convertCarbonInput(expdata.input);

% MDV entries are sums and products of fractions in [0, 1] obtained by sparse linear solves;
% observed rounding is below 1e-13, so 1e-10 separates rounding from a real change
tol = 1e-10;

%% output fields, MDV lengths, normalisation and nonnegativity

output = slvrEMU_fast(v0, glucoseInput);
expectedNames = {'xalaL011'; 'xalaL111'; 'xasnL0111'; 'xasnL1100'; 'xasnL1111'; 'xaspL0111'; ...
    'xaspL1100'; 'xaspL1111'; 'xglnL01111'; 'xglnL11111'; 'xgluL01111'; 'xgluL11111'; ...
    'xgly01'; 'xgly11'; 'xhisL011111'; 'xhisL111111'; 'xileL011111'; 'xleuL011111'; ...
    'xlysL011111'; 'xlysL111111'; 'xmetL01111'; 'xmetL11111'; 'xpheL011111111'; ...
    'xpheL110000000'; 'xpheL111111111'; 'xproL01111'; 'xserL011'; 'xserL110'; 'xserL111'; ...
    'xthrL0111'; 'xthrL1111'; 'xtyrL011111111'; 'xtyrL110000000'; 'xtyrL111111111'; ...
    'xvalL01111'; 'xvalL11111'};
assert(isequal(fieldnames(output), expectedNames));
for k = 1:numel(expectedNames)
    fragmentName = expectedNames{k};
    mdv = output.(fragmentName);
    % the fragment name ends with one digit per carbon; 1 marks a carbon in the fragment,
    % so the MDV has (number of 1s + 1) mass isotopomers M+0 ... M+n
    carbonPattern = regexp(fragmentName, '[01]+$', 'match', 'once');
    assert(iscolumn(mdv) && numel(mdv) == nnz(carbonPattern == '1') + 1);
    % a mass distribution sums to one and has no negative fraction
    assert(abs(sum(mdv) - 1) < tol);
    assert(all(mdv > -tol));
end

%% an unlabelled glucose input leaves every fragment unlabelled

% all glucose molecules are the isotopomer 000000; the cumomer vector of this input is the
% one built by idv2cdv, as convertCarbonInput expects
unlabelledIdv = zeros(64, 1);
unlabelledIdv(1) = 1;
unlabelledOutput = slvrEMU_fast(v0, convertCarbonInput(idv2cdv(6) * unlabelledIdv));
for k = 1:numel(expectedNames)
    mdv = unlabelledOutput.(expectedNames{k});
    expectedMdv = [1; zeros(numel(mdv) - 1, 1)];
    assert(max(abs(mdv - expectedMdv)) < tol);
end

%% agreement with the unoptimised EMU solver slvrEMU of the same model

referenceOutput = slvrEMU(v0, glucoseInput);
for k = 1:numel(expectedNames)
    assert(max(abs(output.(expectedNames{k}) - referenceOutput.(expectedNames{k}))) < tol);
end

%% Tier 5 reference values (first run, 2026-11-15, MATLAB R2025a, no optimisation solver)

assert(max(abs(output.xalaL011 - [0.59417882258740251; 0.38977754190256475; 0.016043635510032718])) < tol);
assert(max(abs(output.xgly01 - [0.97913471534348751; 0.02086528465651246])) < tol);
assert(max(abs(output.xserL111 - [0.6038014688606953; 0.37596959833798926; ...
    0.019814463155872937; 0.00041446964544248098])) < tol);
assert(max(abs(output.xpheL111111111 - [0.24885233052750122; 0.42209985047241627; ...
    0.25480272877126392; 0.066200169745492823; 0.0075977929511622305; ...
    0.00043395591446879537; 1.2969058318846074e-05; 2.010249051189866e-07; ...
    1.5299457638277504e-09; 4.5248935906381501e-12])) < tol);

% restore the warning state changed by solveLin
warning(nearlySingularState);

% remove the global caches created by cdv2idv and idv2cdv
newGlobals = setdiff(who('global'), globalsBefore);
for k = 1:numel(newGlobals)
    clearvars('-global', newGlobals{k});
end

% put back the solver files present before the test and remove the ones it generated
for k = 1:numel(c13Files)
    if c13Existed(k)
        copyfile(fullfile(c13Backup, c13Files{k}), c13Dir);
    elseif exist(fullfile(c13Dir, c13Files{k}), 'file') == 2
        delete(fullfile(c13Dir, c13Files{k}));
    end
end
rmdir(c13Backup, 's');
rehash;
clear convertCarbonInput slvrCumomer slvrCumomer_fast slvrEMU slvrEMU_fast

% change the directory
cd(currentDir)
